import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"4、【蒙】 坎下艮上","description":"周易口訣義 - 4、【蒙】 坎下艮上","frontmatter":{"title":"4、【蒙】 坎下艮上","description":"周易口訣義 - 4、【蒙】 坎下艮上"},"headers":[],"relativePath":"classics/koujueyi/006.md","filePath":"classics/koujueyi/006.md"}'),r={name:"classics/koujueyi/006.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_4、【蒙】-坎下艮上" tabindex="-1">4、【蒙】 坎下艮上 <a class="header-anchor" href="#_4、【蒙】-坎下艮上" aria-label="Permalink to “4、【蒙】 坎下艮上”">​</a></h1><p>彖曰：「蒙」，山下有險，險而止，蒙。「蒙亨」，以亨行時中也。「匪我求童蒙，童蒙求我」，志應也。「初筮告」，以剛中也。「再三瀆，瀆則不告」，瀆蒙也。蒙以養正，聖功也。</p><p>象曰：山下出泉，「蒙」，君子以果行育德。</p><p>初六：發矇，利用刑人，用說桎梏，以往，吝。</p><p>象曰：「利用刑人」，以正法也。</p><p>九二：包蒙，吉。納婦吉。子克家。</p><p>象曰：「子克家」，剛柔接也。</p><p>六三：勿用取女，見金夫，不有躬，無攸利。</p><p>象曰：「勿用取女」，行不順也。</p><p>六四，困蒙，吝。</p><p>象曰：「困蒙」之吝，獨遠實也。</p><p>六五，童蒙吉。</p><p>象曰：「童蒙」之吉，順以巽也。</p><p>上九，擊蒙，不利為寇，利御冠。</p><p>象曰：利用「禦寇」，上下順也。</p><p>解讀</p><p>「蒙亨」者，蒙者童稚之名，闇昧之義。處「童蒙」之時，所願獲通，故曰「蒙亨」。「匪我求童蒙，童蒙求我」者，匪，非也，「童蒙」者謂五也，「我」謂二也。五處「童蒙」之時，當求九二之明師也。「再三瀆，瀆則不告」者，瀆，亂也，矇昧之人，心多疑惑，若明師與之決蒙，須一理而說，使其曉悟。若其廣說引諭至於繁多，即蒙者瀆亂，亂即還同不告。「利貞」者，蒙而未曉，心須養正乃通，至聖之功也。</p><p>象曰「山下出泉，蒙，君子以果行育德」者，王氏雲：「山下出泉，未知所適，蒙之象也。」君子處是時而未獲通，當須果決為行，育養己德，德立道成，可以適蒙之險。</p><p>「初六，發矇，利用刑人，用說桎梏，以往吝」者，初六雖是闇昧，而與九二相近，即是親比明師，以去蒙暗。蒙既顯發，即心無凝滯，乃能利用刑罰罪人，又能脫去罪人桎梏之象，言其明於法律，舉事合宜。凡刑罰之道，不可常行，鞭撲不可弛之家，刑罰不可弛之國。若用刑不已，民所不堪，即有悔吝之道，故曰「以往吝」。爾雅雲：「杽謂之桎，械謂之梏也。」</p><p>「九二，包蒙，吉。納婦吉，子克家」者，凡言「婦」者，配己成德。九二剛陽之德而居中，群陰悉來，物來歸己，而能納之，故曰「包蒙吉」也。心既弘通，不拒於物，即配德者歸焉，故曰「納婦吉」也。剛而處中，納此匹配，是能幹濟家事，施之子孫，而能克荷家事，故曰「子克家」也。</p><p>「六三，勿用取女，見金夫，不有躬，無攸利」者，「蒙」之為體，陰先求陽，弱先求強。六三是陰柔，即是先求上九者也。喻之人事，是女先求於男也。女以婉順為德，待禮而行，今既先求於男，故不可取也。「見金夫，不有躬，無攸利」者，金，剛也。上九剛夫而乃往就之，是無閨閣之德，故不可取之而無所利也。六四「困蒙，吝」者，既不近明師，無人顯發其暗，深可鄙也。「六五童蒙，吉」者，柔而處尊，不自任察，但委付於二，不勞己之聰明，猶如童稚之人，自可獲吉，如成王委用周公之義。</p><p>上九：擊蒙，不利為寇。「利禦寇」者，上九陽明之德，處眾陰之上，能於眾陰擊去蒙暗，故曰「擊蒙」也。眾陰親託，皆願求安，能為群陰去除寇難，則荷戴彌深。若因人之隙，便生苟且而以取之，則眾陰叛矣，故云不利為寇而利用禦寇也。</p>',22)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
